export const MAX_CONTEXT_SENTENCE_CHARS = 300;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Validate an untrusted request body. Returns the request or a reason. */
export function parseTutorRequest(raw: unknown): { ok: true; request: TutorRequest } | { ok: false; reason: string } {
  if (!raw || typeof raw !== 'object') return { ok: false, reason: 'body must be an object' };
  const r = raw as Record<string, unknown>;
  const kind = r.kind;
  if (typeof kind !== 'string' || !TUTOR_KINDS.includes(kind as TutorKind)) return { ok: false, reason: 'unknown kind' };
  if (kind === 'mistakes') return { ok: true, request: { kind } };
  const wordId = r.wordId;
  if (typeof wordId !== 'string' || !UUID.test(wordId)) return { ok: false, reason: 'wordId must be a UUID' };
  switch (kind) {
    case 'explain':
    case 'examples':
    case 'exercises':
      return { ok: true, request: { kind, wordId } };
    case 'compare': {
      const others = r.others;
      if (!Array.isArray(others) || others.length < 1 || others.length > 3) return { ok: false, reason: 'others must have 1–3 words' };
      if (!others.every((o) => typeof o === 'string' && o.trim().length > 0 && o.length <= 40)) return { ok: false, reason: 'invalid word in others' };
      const cleaned = [...new Set(others.map((o) => (o as string).trim().toLowerCase()))];
      return { ok: true, request: { kind, wordId, others: cleaned } };
    }
    case 'context': {
      const sentence = r.sentence;
      if (typeof sentence !== 'string') return { ok: false, reason: 'sentence is required' };
      const s = sentence.replace(/\s+/g, ' ').trim();
      if (s.length < 3 || s.length > MAX_CONTEXT_SENTENCE_CHARS) return { ok: false, reason: `sentence must be 3–${MAX_CONTEXT_SENTENCE_CHARS} characters` };
      return { ok: true, request: { kind, wordId, sentence: s } };
    }
  }
  return { ok: false, reason: 'unknown kind' };
}

/** Stable identity of a request, used for caching on both sides. */
export function requestKey(r: TutorRequest): string {
  switch (r.kind) {
    case 'mistakes':
      return 'mistakes';
    case 'compare':
      return `compare:${r.wordId}:${[...r.others].sort().join(',')}`;
    case 'context':
      return `context:${r.wordId}:${r.sentence}`;
    default:
      return `${r.kind}:${r.wordId}`;
  }
}
